/*
 * A048687  a(n) is the number of classes generated by function A001221 when
 *          applied to binomial coefficients.
 * https://oeis.org/A048687
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = number of distinct values of A001221(binomial(n,k)) for k
 *            = 0..n A001221(x) is the number of distinct prime factors of x.
 *            For C(n,k) let e_p(m) be the exponent of prime p in m!. Then for
 *            each prime p e_p(C(n,k)) = e_p(n!) - e_p(k!) - e_p((n-k)!).
 *            e_p(C(n,k)) > 0 iff the prime p occurs in t...
 * Range:     u8 n <= 1000, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>

/* sieve of Eratosthenes: primes up to n, stored in *primes,
   *cnt receives the number of primes. */
static void build_primes_upto(idx_t n, uint64_t **primes, size_t *cnt)
{
    size_t N = (size_t)n;
    bool *is_comp = (bool*)calloc(N + 1, sizeof(bool));
    size_t pcnt = 0;
    for (size_t i = 2; i <= N; ++i) {
        if (!is_comp[i]) {
            (*primes)[pcnt++] = (uint64_t)i;
            if (i * i <= N)
                for (size_t j = i * i; j <= N; j += i)
                    is_comp[j] = true;
        }
    }
    *cnt = pcnt;
    free(is_comp);
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;
    size_t N = (size_t)n;

    /* generate primes up to n */
    size_t pcnt = 0;
    uint64_t *primes = (uint64_t*)malloc((N + 1) * sizeof(uint64_t));
    build_primes_upto(n, &primes, &pcnt);

    /* store e_p(m!) in a flat array: exp[pi*(N+1)+m] */
    size_t exp_stride = N + 1;
    uint16_t *exp = (uint16_t*)malloc(pcnt * exp_stride * sizeof(uint16_t));
    for (size_t pi = 0; pi < pcnt; ++pi) {
        exp[pi * exp_stride + 0] = 0;              /* e_p(0!) = 0 */
        uint64_t p = primes[pi];
        for (size_t m = 1; m <= N; ++m) {
            uint64_t tmp = m;
            unsigned cnt = 0;
            while (tmp % p == 0) {
                tmp /= p;
                ++cnt;
            }
            exp[pi * exp_stride + m] = exp[pi * exp_stride + m - 1] + cnt;
        }
    }

    /* e_p(n!) for all primes */
    uint16_t *ep_n = (uint16_t*)malloc(pcnt * sizeof(uint16_t));
    for (size_t pi = 0; pi < pcnt; ++pi)
        ep_n[pi] = exp[pi * exp_stride + N];

    /* count distinct omega values */
    bool *seen = (bool*)calloc(pcnt + 1, sizeof(bool));  /* max omega <= pcnt */
    unsigned distinct = 0;

    for (size_t k = 0; k <= N; ++k) {
        unsigned omega = 0;
        size_t km = k;
        size_t kmc = N - k;
        for (size_t pi = 0; pi < pcnt; ++pi) {
            uint16_t e = ep_n[pi];
            uint16_t ek = exp[pi * exp_stride + km];
            uint16_t ekc = exp[pi * exp_stride + kmc];
            if (e > ek + ekc) ++omega;
        }
        if (!seen[omega]) {
            seen[omega] = true;
            ++distinct;
        }
    }

    /* clean up */
    free(primes);
    free(exp);
    free(ep_n);
    free(seen);

    return (seq_t)distinct;
}
